int i = 0;
do
{
    Console.WriteLine(i);
    i++;
} while (i < 3);

int n = 5;
do
{
    Console.WriteLine(n);
    n--;
} while (n > 0);

string word = "Cat";
int index = 0;
while (index < word.Length)
{
    Console.WriteLine(word[index]);
    index++;
}

int outer = 1;
while (outer <= 2)
{
    int inner = 1;
    while (inner <= 2)
    {
        Console.WriteLine($"{outer},{inner}");
        inner++;
    }
    outer++;
}

int i = 0;
while (i < 5)
{
    i++;
    if (i == 3)
        continue;
    Console.WriteLine(i);
}

